-- Breaking DDL that violates N / N-1 compatibility
ALTER TABLE invoices RENAME COLUMN billing_zip TO postal_code;
ALTER TABLE invoices ADD COLUMN tax_jurisdiction VARCHAR(16) NOT NULL;

ALTER TABLE invoices
  ADD COLUMN IF NOT EXISTS postal_code VARCHAR(16),
  ADD COLUMN IF NOT EXISTS tax_jurisdiction VARCHAR(16) DEFAULT 'PENDING';

CREATE OR REPLACE FUNCTION sync_invoices_postal_code() RETURNS TRIGGER AS $$
BEGIN
  IF NEW.postal_code IS NULL THEN NEW.postal_code := NEW.billing_zip; END IF;
  IF NEW.billing_zip IS NULL THEN NEW.billing_zip := NEW.postal_code; END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

SET lock_timeout = '2000ms';
ALTER TABLE invoices ADD CONSTRAINT chk_tax_jurisdiction_nn
  CHECK (tax_jurisdiction IS NOT NULL) NOT VALID;
ALTER TABLE invoices VALIDATE CONSTRAINT chk_tax_jurisdiction_nn;

sections.content:
## Detailed Design

### Phase 1: Expand (Pre-Deploy Migration `V42__expand_invoices.sql`)
```sql
SET lock_timeout = '2000ms';
ALTER TABLE invoices
  ADD COLUMN postal_code VARCHAR(16),
  ADD COLUMN tax_jurisdiction VARCHAR(16) DEFAULT 'PENDING';

CREATE OR REPLACE FUNCTION sync_invoices_postal_code()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.postal_code IS NULL AND NEW.billing_zip IS NOT NULL THEN
    NEW.postal_code := NEW.billing_zip;
  ELSIF NEW.billing_zip IS NULL AND NEW.postal_code IS NOT NULL THEN
    NEW.billing_zip := NEW.postal_code;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_invoices_postal
BEFORE INSERT OR UPDATE ON invoices
FOR EACH ROW EXECUTE FUNCTION sync_invoices_postal_code();
```

### Phase 2: Application Cutover (Green v42)
Green reads `COALESCE(postal_code, billing_zip)` and writes `postal_code` and `tax_jurisdiction`. If Green fails, ALB flips back to Blue (v41), which continues reading/writing `billing_zip` while the trigger keeps `postal_code` populated.

### Phase 3: Backfill & Validate (Post-Stabilization)
Once Green is 100% stable and Blue is drained, backfill historical `postal_code` and `tax_jurisdiction` in throttled batches, then add `CHECK (tax_jurisdiction IS NOT NULL) NOT VALID` and `VALIDATE CONSTRAINT`.

### Phase 4: Contract (Release v43)
In the next release, drop `trg_sync_invoices_postal` and `ALTER TABLE invoices DROP COLUMN billing_zip;`.
